export const STORAGE_KEY='llm-foundations-v1';
export const NOTE_FIELDS=['Question and prediction','Data source and split limitations','Run folders and checkpoint steps','Fixed settings','Changed setting','Tokenizer identity','Observed losses, sample behavior, and elapsed time','What the evidence supports','What it does not establish','Next experiment'];
export const EVIDENCE=['Data note: source, permitted use, splits, counts, and leakage limits','Tokenizer: whitespace and Unicode round trips, saved identity, vocabulary size','Run folder: manifest, initial/final metrics, tokenizer, checkpoint, result status','Checkpoint: inspect, evaluate, three fixed prompts, and resume in a new folder','Controlled comparison: hypothesis, one changed setting, controls, time, limitations','Explanation: text → optimizer update → generated text'];
export const shortTitles=['Set up your environment','Follow one prediction','Explore tokenizers','Prepare your data','Learn about embeddings','Understand attention','Build the model','Train model weights','Read the evidence','Save, resume, generate','Change one thing','Connect to modern models','Gather your evidence'];
export const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function blankState(){return {format:'llm-foundations-progress-v1',edition:'2026-09-26',theme:'light',os:'wsl',lastLesson:null,lessons:{},notes:Object.fromEntries(NOTE_FIELDS.map(x=>[x,''])),evidence:EVIDENCE.map(()=>({note:'',reviewed:false})),runs:[],updatedAt:null};}
export function saveState(storage,state){try{storage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{return false;}}
export function loadState(storage){try{const raw=storage.getItem(STORAGE_KEY);return {state:raw?validateState(JSON.parse(raw)):blankState(),error:null};}catch{return {state:blankState(),error:'Saved progress could not be read. The stored copy has not been replaced. Export the current session before leaving.'};}}
export function nextLesson(state){if(state.lastLesson&&!state.lessons[state.lastLesson]?.read)return state.lastLesson;return Array.from({length:13},(_,i)=>String(i).padStart(2,'0')).find(id=>!state.lessons[id]?.read)??state.lastLesson??'00';}
export function visitLesson(state,id){if(!/^0[0-9]$|^1[0-2]$/.test(id))throw Error('Unknown lesson');state.lastLesson=id;state.lessons[id]={...state.lessons[id],reading:true};return state;}
export function setProgress(state,id,kind,value){if(!['read','practiced','checked'].includes(kind)||typeof value!=='boolean')throw Error('Invalid progress');visitLesson(state,id);state.lessons[id][kind]=value;return state;}
export function validateTokenizer(t){if(!t||t.format!=='teaching-byte-bpe-v1'||!Array.isArray(t.merges)||t.merges.length>767)throw Error('Unsupported tokenizer format or size.');t.merges.forEach((p,i)=>{if(!Array.isArray(p)||p.length!==2||p.some(x=>!Number.isInteger(x)||x<0||x===256||x>=257+i))throw Error('Tokenizer merges must reference earlier non-EOS IDs.');});return t;}
export function tokenize(text,t){validateTokenizer(t);let ids=Array.from(new TextEncoder().encode(text));const pieces=Array.from({length:256},(_,i)=>[i]);pieces[256]=[];const trace=[];t.merges.forEach(([left,right],i)=>{const id=257+i;pieces[id]=[...pieces[left],...pieces[right]];const out=[];let count=0;for(let j=0;j<ids.length;j++){if(ids[j]===left&&ids[j+1]===right){out.push(id);j++;count++;}else out.push(ids[j]);}if(count)trace.push({id,left,right,count,before:ids.length,after:out.length});ids=out;});const decoded=new TextDecoder('utf-8',{fatal:true}).decode(new Uint8Array(ids.flatMap(id=>pieces[id])));return {ids,pieces,decoded,bytes:Array.from(new TextEncoder().encode(text)),roundTrip:decoded===text,trace};}
export function visiblePiece(bytes){try{return new TextDecoder('utf-8',{fatal:true}).decode(new Uint8Array(bytes)).replace(/ /g,'␠').replace(/\n/g,'↵').replace(/\t/g,'⇥');}catch{return bytes.map(x=>x.toString(16).padStart(2,'0').toUpperCase()).join(' ');}}
export function prediction(sequence,position){if(!Array.isArray(sequence)||sequence.length<2||sequence.some(x=>!Number.isInteger(x)||x<0)||!Number.isInteger(position)||position<0||position>=sequence.length-1)throw Error('Invalid sequence or position');return {inputs:sequence.slice(0,-1),targets:sequence.slice(1),allowed:sequence.slice(0,position+1),target:sequence[position+1]};}
export function shapes({batch,context,width,heads,vocab,layers}){if([batch,context,width,heads,vocab,layers].some(x=>!Number.isInteger(x)||x<1||x>4096)||width%heads)throw Error('Width must divide evenly by heads. Choose, for example, width 64 and 4 heads.');return {input:[batch,context],embedding:[batch,context,width],attention:[batch,heads,context,width/heads],scores:[batch,heads,context,context],output:[batch,context,vocab],tokenParameters:vocab*width,positionParameters:context*width,outputParameters:vocab*width,headWidth:width/heads};}
const finite=v=>typeof v==='number'&&Number.isFinite(v);
const int=v=>Number.isInteger(v)&&v>=0;
export function validateRun(run){if(!run||!run.manifest||!Array.isArray(run.metrics)||!run.metrics.length)throw Error('Include manifest.json and nonempty metrics.jsonl. No missing value is treated as zero.');const m=run.manifest;if(m.format!=='foundations-lab-v1')throw Error('This is not a foundations-lab-v1 manifest.');if(Object.hasOwn(m,'parameters')&&(!Number.isSafeInteger(m.parameters)||m.parameters<0))throw Error('Parameter count must be a nonnegative safe integer when supplied.');validateTokenizer(m.tokenizer);if(!m.config||m.config.vocab_size!==257+m.tokenizer.merges.length)throw Error('Vocabulary size and tokenizer do not match.');shapes({batch:m.batch_size,context:m.config.context,width:m.config.width,heads:m.config.heads,vocab:m.config.vocab_size,layers:m.config.layers});if(!/^[a-f0-9]{64}$/.test(m.tokenizer_sha256||''))throw Error('Missing tokenizer identity.');if(!m.data?.train||!m.data?.validation||!m.evaluation||!int(m.evaluation.batches)||!m.evaluation.batches||!int(m.evaluation.seed)||m.evaluation.context!==m.config.context)throw Error('Missing or incompatible evaluation protocol.');for(const d of [m.data.train,m.data.validation])if(!/^[a-f0-9]{64}$/.test(d.sha256||'')||!int(d.documents))throw Error('Missing data identity or document count.');let last=-1;let elapsed=-1;for(const r of run.metrics){if(!int(r.step)||r.step<=last||!['initial','training','resumed'].includes(r.phase)||!finite(r.train_loss)||r.train_loss<0||!finite(r.validation_loss)||r.validation_loss<0||!finite(r.elapsed_seconds)||r.elapsed_seconds<elapsed||(r.validation_perplexity!==null&&(!finite(r.validation_perplexity)||r.validation_perplexity<1)))throw Error('Malformed metrics: steps must increase and measured values must be finite.');last=r.step;elapsed=r.elapsed_seconds;}const result=run.result;if(result!==null&&result!==undefined){if(typeof result!=='object'||Array.isArray(result))throw Error('Result must be an object when supplied.');if(!['completed','interrupted','failed'].includes(result.status))throw Error('Unknown result status.');const needsLimit=result.status!=='failed'||Object.hasOwn(result,'requested_final_step');if(!int(result.step)||result.step<last||(needsLimit&&(!int(result.requested_final_step)||result.step>result.requested_final_step))||(result.status==='completed'&&(result.step!==last||result.step!==result.requested_final_step)))throw Error('Result status and recorded steps do not agree.');if(Object.hasOwn(result,'error')&&typeof result.error!=='string')throw Error('Result error must be plain text when supplied.');}if(run.sample!==null&&run.sample!==undefined&&typeof run.sample!=='string')throw Error('Sample must be plain text.');return {name:typeof run.name==='string'?run.name.slice(0,120):'Imported experiment',manifest:m,metrics:run.metrics,result:result??null,sample:run.sample??null};}
export async function verifyRunIdentity(run){validateRun(run);if(!globalThis.crypto?.subtle)throw Error('This browser cannot verify tokenizer identity here. Use a secure site or localhost.');const text='{"format": "teaching-byte-bpe-v1", "merges": '+JSON.stringify(run.manifest.tokenizer.merges).replace(/,/g,', ').replace(/\], \[/g,'], [')+'}';const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));const hash=Array.from(new Uint8Array(bytes),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==run.manifest.tokenizer_sha256)throw Error('Tokenizer fingerprint does not match its merge rules.');return run;}
export function parseRunFiles(files){const byName=Object.fromEntries(files.map(f=>[f.name,f.text]));if(!byName['manifest.json']||!byName['metrics.jsonl'])throw Error('Select manifest.json and metrics.jsonl together. result.json and sample.txt are optional.');let run;try{run={name:'Imported experiment',manifest:JSON.parse(byName['manifest.json']),metrics:byName['metrics.jsonl'].split(/\r?\n/).filter(x=>x.trim()).map(x=>JSON.parse(x)),result:Object.hasOwn(byName,'result.json')?JSON.parse(byName['result.json']):null,sample:byName['sample.txt']??null};}catch{throw Error('A selected JSON or JSONL file is malformed. Your saved experiments are unchanged.');}return validateRun(run);}
export function validateState(value){if(!value||value.format!=='llm-foundations-progress-v1'||value.edition!=='2026-09-26')throw Error('Incompatible progress backup.');const s=blankState();if(!value.lessons||typeof value.lessons!=='object'||Array.isArray(value.lessons))throw Error('Invalid lesson progress');for(const [id,v] of Object.entries(value.lessons)){if(!/^0[0-9]$|^1[0-2]$/.test(id)||!v||typeof v!=='object')throw Error('Invalid lesson progress');s.lessons[id]={};for(const k of ['reading','read','practiced','checked'])if(k in v){if(typeof v[k]!=='boolean')throw Error('Invalid progress flag');s.lessons[id][k]=v[k];}}
if(value.lastLesson!==null&&(!/^0[0-9]$|^1[0-2]$/.test(value.lastLesson)))throw Error('Invalid continuation');s.lastLesson=value.lastLesson;s.theme=['light','dark'].includes(value.theme)?value.theme:'light';s.os=['wsl','windows'].includes(value.os)?value.os:'wsl';for(const field of NOTE_FIELDS){if(typeof value.notes?.[field]!=='string'||value.notes[field].length>20000)throw Error('Invalid notebook text');s.notes[field]=value.notes[field];}if(!Array.isArray(value.evidence)||value.evidence.length!==EVIDENCE.length)throw Error('Invalid evidence checklist');s.evidence=value.evidence.map(e=>{if(!e||typeof e.note!=='string'||e.note.length>20000||typeof e.reviewed!=='boolean'||(e.reviewed&&!e.note.trim()))throw Error('Reviewed evidence needs an artifact reference.');return {note:e.note,reviewed:e.reviewed};});if(!Array.isArray(value.runs)||value.runs.length>20)throw Error('Too many saved runs');s.runs=value.runs.map(validateRun);s.updatedAt=typeof value.updatedAt==='string'?value.updatedAt:null;return s;}
export function mergeState(current,incoming){const a=validateState(current),b=validateState(incoming);for(const [id,v] of Object.entries(b.lessons)){a.lessons[id]??={};for(const k of ['reading','read','practiced','checked'])a.lessons[id][k]=!!(a.lessons[id][k]||v[k]);}for(const field of NOTE_FIELDS)if(b.notes[field]&&b.notes[field]!==a.notes[field])a.notes[field]=[a.notes[field],b.notes[field]].filter(Boolean).join('\n\n[Imported note]\n');b.evidence.forEach((e,i)=>{if(e.note&&e.note!==a.evidence[i].note)a.evidence[i].note=[a.evidence[i].note,e.note].filter(Boolean).join('\n[Imported evidence]\n');a.evidence[i].reviewed=a.evidence[i].reviewed||e.reviewed;});const seen=new Set(a.runs.map(r=>JSON.stringify(r)));b.runs.forEach(r=>{if(!seen.has(JSON.stringify(r))){a.runs.push(r);seen.add(JSON.stringify(r));}});if(!a.lastLesson)a.lastLesson=b.lastLesson;return validateState(a);}
export function resolveLink(url,base){if(/^https?:\/\//.test(url))return url;if(/^[a-z]+:/i.test(url)||url.startsWith('//'))return '#/';const parts=base.split('/').slice(0,-1);url.split('/').forEach(p=>{if(p==='..')parts.pop();else if(p!=='.')parts.push(p);});const path=parts.join('/');if(/^lessons\/\d{2}-.+\.md$/.test(path))return '#/lesson/'+path.slice(8,10);if(path==='labs/WORKBOOK.md')return '#/labs';if(path==='reference/GLOSSARY.md')return '#/glossary';if(path.endsWith('.md'))return '#/reference/'+encodeURIComponent(path);return 'course/'+path;}
export function inline(text,base){const saved=[];const hold=html=>`\u0000${saved.push(html)-1}\u0000`;let s=String(text).replace(/`([^`]+)`/g,(_,c)=>hold('<code>'+escapeHTML(c)+'</code>'));s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,url)=>hold('<a href="'+escapeHTML(resolveLink(url,base))+'"'+(/^https?:/.test(url)?' target="_blank" rel="noopener noreferrer"':'')+'>'+escapeHTML(label)+'</a>'));s=escapeHTML(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');return s.replace(/\u0000(\d+)\u0000/g,(_,i)=>saved[+i]);}
export function markdown(md,base='START_HERE.md',{omitTitle=false,answers=true,os='wsl'}={}){const lines=md.split(/\r?\n/);let html='',i=0,heading=0;const inl=s=>inline(s,base);while(i<lines.length){let line=lines[i];if(!line.trim()){i++;continue;}if(line.startsWith('```')){const lang=line.slice(3).trim();const code=[];i++;while(i<lines.length&&!lines[i].startsWith('```'))code.push(lines[i++]);i++;const raw=code.join('\n');if((lang==='powershell'&&os!=='windows')||(lang==='bash'&&os==='windows'))continue;const display=os==='windows'&&lang==='text'?raw.replace(/\bpython(?=\s)/g,'.\\.venv\\Scripts\\python.exe'):raw;html+=`<div class="code-block"><div class="code-head"><span>${['text','bash','powershell'].includes(lang)&&/(python|venv)/.test(raw)?'Run locally · llm-foundations-v2/':escapeHTML(lang||'Example')}</span><button type="button" class="copy-btn" data-copy="${escapeHTML(display)}">Copy</button></div><pre><code>${escapeHTML(display)}</code></pre></div>`;continue;}if(/^#{1,6} /.test(line)){const level=line.match(/^#+/)[0].length;if(!(omitTitle&&level===1))html+=`<h${level} id="section-${heading++}">${inl(line.slice(level+1))}</h${level}>`;i++;continue;}if(line.startsWith('|')&&i+1<lines.length&&/^\|[\s:|-]+\|?$/.test(lines[i+1])){const cells=l=>l.trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim());html+='<div class="table-wrap" tabindex="0" role="region" aria-label="Lesson table"><table><thead><tr>'+cells(line).map(c=>'<th scope="col">'+inl(c)+'</th>').join('')+'</tr></thead><tbody>';i+=2;while(i<lines.length&&lines[i].startsWith('|'))html+='<tr>'+cells(lines[i++]).map(c=>'<td>'+inl(c)+'</td>').join('')+'</tr>';html+='</tbody></table></div>';continue;}if(/^([-*]|\d+\.) /.test(line)){const ordered=/^\d/.test(line),tag=ordered?'ol':'ul';html+=`<${tag}>`;while(i<lines.length&&/^([-*]|\d+\.) /.test(lines[i]))html+='<li>'+inl(lines[i++].replace(/^([-*]|\d+\.) /,''))+'</li>';html+=`</${tag}>`;continue;}const para=[line];i++;while(i<lines.length&&lines[i].trim()&&!/^(#|```|\||[-*] |\d+\. )/.test(lines[i]))para.push(lines[i++]);const text=para.join(' ');if(answers&&/^\*\*Answers?:\*\*/.test(text))html+=`<details class="answer"><summary>Reveal answer explanation</summary><p>${inl(text)}</p></details>`;else if(/^\*\*(Common snag|Common misconception|Boundary):/.test(text))html+=`<details class="deeper"><summary>${inl(text.match(/^\*\*([^*]+)\*\*/)[1])} Read a little deeper</summary><p>${inl(text)}</p></details>`;else html+='<p'+(/^\*\*Stop here:/.test(text)?' class="stopping"':'')+'>'+inl(text)+'</p>';}
return html;}

